import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, fin, T, DUR, Camara, Contador, Textura, Profundidad, Brillo, Paso, seguir, enCamino, tono, Regla, Chip, Ondas, Destello, sacudida, golpe, Recorrido, Easing, interpolate, clamp, spring, h, FONT} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
// parada de camara que nunca deja ver el borde del mundo (n paneles de 1080 de ancho)
const W = (t: number, x: number, y: number, z: number, n = 1) => ({t, x: cl(x, 540 / z, 1080 * n - 540 / z), y: cl(y, 1000 / z, 1920 - 920 / z), zoom: z});
const GOLD = '#FFC83D';
const RED = '#FF4D4D';
// SFX: nunca dos a menos de 0,27 s aunque la voz real cambie los tiempos
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};

// ---------- piezas dibujadas ----------
const Panel: React.FC<{i: number; tipo?: 'piel' | 'celulas' | 'fibra' | 'papel'; base: string; linea: string; luz?: string; semilla?: number; br?: [number, number, number, string]}> = ({i, tipo = 'fibra', base, linea, luz = 'rgba(255,255,255,0.14)', semilla = 1, br}) => (
  <div style={{position: 'absolute', left: i * 1080, top: 0, width: 1080, height: 1920, overflow: 'hidden'}}>
    <Textura tipo={tipo} base={base} linea={linea} luz={luz} semilla={semilla} />
    {br && <Brillo x={br[0]} y={br[1]} r={br[2]} color={br[3]} />}
  </div>
);
const Mundo: React.FC<{n?: number; children: React.ReactNode}> = ({n = 1, children}) => (
  <svg width={1080 * n} height={1920} style={{position: 'absolute', left: 0, top: 0}}>{children}</svg>
);
const Tx: React.FC<{x: number; y: number; s?: number; c?: string; a?: 'start' | 'middle' | 'end'; r?: number; o?: number; children: React.ReactNode}> = ({x, y, s = 40, c = '#fff', a = 'middle', r = 0, o = 1, children}) => (
  <text x={x} y={y} textAnchor={a} fontFamily={FONT} fontWeight={800} fontSize={s} fill={c} opacity={o} transform={`rotate(${r} ${x} ${y})`}>{children}</text>
);

const Bill: React.FC<{x: number; y: number; r?: number; k?: number; txt?: string; tint?: string; halo?: string; mal?: number}> = ({x, y, r = 0, k = 1, txt = '20', tint = '#b4d9a2', halo, mal = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    {halo && <ellipse rx={240} ry={160} fill={halo} opacity={0.4} />}
    <rect x={-146} y={-60} width={304} height={144} rx={14} fill="rgba(0,0,0,0.35)" />
    <rect x={-150} y={-70} width={300} height={140} rx={14} fill={tint} stroke="#3f6b3a" strokeWidth={5} />
    <rect x={-134} y={-54} width={268} height={108} rx={9} fill="none" stroke="#3f6b3a" strokeWidth={2.5} opacity={0.65} />
    <circle r={42} fill="rgba(255,255,255,0.35)" stroke="#3f6b3a" strokeWidth={3} />
    <text y={15} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={txt.length > 2 ? 32 : 46} fill="#2f5a2b">{txt}</text>
    <text x={-122} y={-28} fontFamily={FONT} fontWeight={800} fontSize={26} fill="#2f5a2b">$</text>
    <text x={100} y={50} fontFamily={FONT} fontWeight={800} fontSize={26} fill="#2f5a2b">$</text>
    <path d="M -150 -70 L 24 -70 L -56 70 L -150 70 Z" fill="rgba(255,255,255,0.16)" />
    {mal > 0.01 && (
      <g opacity={cl(mal * 1.4)}>
        <path d={`M -150 -70 L ${-150 + 150 * mal} -70 Q ${-110 + 110 * mal} ${-30 + 30 * mal} -150 ${-70 + 110 * mal} Z`} fill="#17140c" />
        <path d={`M 150 70 L ${150 - 170 * mal} 70 Q ${120 - 120 * mal} ${40 - 40 * mal} 150 ${70 - 120 * mal} Z`} fill="#17140c" />
        <circle cx={60} cy={-30} r={30 * mal} fill="#2a2a10" opacity={0.8} />
        <circle cx={-40} cy={40} r={22 * mal} fill="#3a4a14" opacity={0.8} />
      </g>
    )}
  </g>
);

const Cartera: React.FC<{x: number; y: number; k?: number; r?: number; grosor?: number; oro?: boolean; abierta?: number}> = ({x, y, k = 1, r = 0, grosor = 1, oro = false, abierta = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <defs>
      <linearGradient id="cuero" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient>
    </defs>
    <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
    {[0, 1, 2].map((i) => <rect key={i} x={-150 + i * 26} y={-150 - 62 * grosor * (1 - i * 0.12) + abierta * -50} width={250} height={90 * grosor + 20} rx={8} fill={['#b4d9a2', '#a3cf92', '#c1e2b2'][i]} stroke="#3f6b3a" strokeWidth={3} transform={`rotate(${(i - 1) * 4})`} />)}
    <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cuero)" stroke="#2c180a" strokeWidth={5} />
    <rect x={-170} y={-100} width={340} height={210} rx={20} fill="none" stroke={oro ? GOLD : '#c9a074'} strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
    <path d="M -190 -40 Q 0 -10 190 -40 L 190 -80 Q 0 -110 -190 -80 Z" fill="rgba(255,255,255,0.10)" />
    <rect x={120} y={-24} width={70} height={64} rx={14} fill={oro ? GOLD : '#7a4c28'} stroke="#2c180a" strokeWidth={4} />
    <circle cx={152} cy={8} r={12} fill={oro ? '#fff2b0' : '#c9a074'} />
  </g>
);

const SK: Record<string, string[]> = {
  clara: ['#f5d2b3', '#e9b98f', '#c48d62', '#8d5a35'], media: ['#e0a878', '#c98f5e', '#9c6a40', '#7a4f2c'], trigueña: ['#d9a56f', '#c08a55', '#94623a', '#6f4527'],
  morena: ['#b9824f', '#9a6a3e', '#7a4f2c', '#4f3018'], oscura: ['#8a5a36', '#6b4226', '#4f2f1a', '#2f1a0c'],
};
const Mano: React.FC<{x: number; y: number; r?: number; k?: number; dedo?: boolean; piel?: string}> = ({x, y, r = 0, k = 1, dedo = true, piel = 'media'}) => {
  const c = SK[piel] || SK.media;
  const F = `url(#pl_${piel})`;
  const L = c[3];
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
      <defs>
        <linearGradient id={`pl_${piel}`} x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor={c[0]} /><stop offset="55%" stopColor={c[1]} /><stop offset="100%" stopColor={c[2]} /></linearGradient>
      </defs>
      <rect x={-64} y={80} width={128} height={420} rx={50} fill={F} stroke={L} strokeWidth={4} />
      <rect x={-80} y={-70} width={160} height={190} rx={56} fill={F} stroke={L} strokeWidth={4} />
      {[[-58, 70], [-20, 55], [20, 60], [58, 75]].map(([fx, fl], i) => (
        <rect key={i} x={fx - 17} y={-70 - (i === 1 && dedo ? 150 : fl)} width={34} height={(i === 1 && dedo ? 150 : fl) + 40} rx={17} fill={F} stroke={L} strokeWidth={3} />
      ))}
      <rect x={-128} y={-20} width={34} height={110} rx={17} fill={F} stroke={L} strokeWidth={3} transform="rotate(-38 -110 60)" />
      <path d="M -80 -20 Q -30 -50 20 -20" stroke="rgba(255,255,255,0.28)" strokeWidth={6} fill="none" strokeLinecap="round" />
    </g>
  );
};

const Moneda: React.FC<{x: number; y: number; k?: number; r?: number; gris?: number; txt?: string}> = ({x, y, k = 1, r = 0, gris = 0, txt = '$'}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <defs>
      <radialGradient id="monG" cx="35%" cy="30%" r="75%"><stop offset="0%" stopColor="#fff2a8" /><stop offset="60%" stopColor="#ffc83d" /><stop offset="100%" stopColor="#a8780f" /></radialGradient>
      <radialGradient id="monX" cx="35%" cy="30%" r="75%"><stop offset="0%" stopColor="#c9c9c9" /><stop offset="60%" stopColor="#8a8a8a" /><stop offset="100%" stopColor="#4d4d4d" /></radialGradient>
    </defs>
    <ellipse cy={40} rx={34} ry={8} fill="rgba(0,0,0,0.3)" />
    <circle r={34} fill="url(#monG)" stroke="#7a560a" strokeWidth={4} />
    <circle r={34} fill="url(#monX)" opacity={gris} />
    <circle r={25} fill="none" stroke="rgba(122,86,10,0.5)" strokeWidth={2} />
    <text y={11} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={32} fill="#7a560a">{txt}</text>
  </g>
);

const Polvo: React.FC<{n?: number; color?: string; vel?: number}> = ({n = 30, color = 'rgba(255,240,210,0.5)', vel = 1}) => {
  const {s} = useS();
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      {Array.from({length: n}).map((_, i) => {
        const x = h(i * 3 + 1) * 1080 + Math.sin(s * 0.6 + i) * 34;
        const y = (((h(i * 7 + 2) * 1920 - s * (14 + h(i) * 26) * vel) % 1920) + 1920) % 1920;
        return <circle key={i} cx={x} cy={y} r={2 + h(i * 5) * 4} fill={color} opacity={0.25 + h(i * 11) * 0.4} />;
      })}
    </svg>
  );
};

const Cel: React.FC<{x: number; y: number; k?: number; r?: number; pantalla?: string; children?: React.ReactNode}> = ({x, y, k = 1, r = 0, pantalla = '#0c1a28', children}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <rect x={-264} y={-512} width={528} height={1044} rx={78} fill="rgba(0,0,0,0.45)" transform="translate(10 16)" />
    <rect x={-260} y={-520} width={520} height={1040} rx={76} fill="#12151c" stroke="#4a5262" strokeWidth={8} />
    <rect x={-232} y={-492} width={464} height={984} rx={54} fill={pantalla} />
    <rect x={-60} y={-480} width={120} height={22} rx={11} fill="#05070a" />
    {children}
  </g>
);

// ---------- composicion comun ----------
const Raiz: React.FC<{tint: string; sem?: number; polvo?: string; children: React.ReactNode}> = ({tint, sem = 3, polvo, children}) => (
  <AbsoluteFill style={{background: '#000'}}>
    {children}
    <AbsoluteFill style={{background: tint, mixBlendMode: 'soft-light'}} />
    {polvo && <Polvo n={22} color={polvo} />}
    <Profundidad manchas={3} semilla={sem} />
  </AbsoluteFill>
);


const ASC = <T extends {t: number}>(a: T[]): T[] => { const o: T[] = []; a.forEach((p) => o.push({...p, t: o.length ? Math.max(p.t, o[o.length - 1].t + 0.05) : p.t})); return o; };
// ---------- tiempos ----------
const ESTAFA = en('estafa'), TE3 = en('te', 3), LLAMAN = en('llaman'), DICEN = en('dicen'), BANCO = en('banco'), IMPUESTOS = en('impuestos'), LUZ = en('luz'), HOY = en('hoy');
const COMO = en('como'), COMPRA = en('compra'), TARJ2 = en('tarjetas', 2), DIME = en('dime'), ATRAS = en('atras');
const DICTAS = en('dictas'), CODIGO = en('codigo'), ELLOS = en('ellos'), IMPOS = en('imposible');
const EN2 = en('en', 2), CUARENTA = en('cuarenta'), REPORTES = en('reportes'), PERDIERON = en('perdieron'), DOSCIENTOS = en('doscientos');
const Y4 = en('y', 4), NADIE2 = en('nadie', 2), QUIEN = en('quien');
const CUELGA = en('cuelga'), LLAMA = en('llama'), NUMERO = en('numero'), FACTURA = en('factura'), NUNCA = en('nunca'), DICTES = en('dictes');
const DALE = en('dale'), CUELGO = en('cuelgo'), PADRES = en('padres');
const AMBAR = 'rgba(255,170,60,0.22)';

// ---------- tarjeta de regalo (sin marcas) ----------
const Tarjeta: React.FC<{x: number; y: number; k?: number; r?: number; raspado?: number; col?: string; gris?: number; vacio?: boolean; quitados?: number; children?: React.ReactNode}> = ({x, y, k = 1, r = 0, raspado = 1, col = GOLD, gris = 0, vacio = false, quitados = 0, children}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <defs>
      <linearGradient id="tjG" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#5b3fd6" /><stop offset="100%" stopColor="#1f9ab0" /></linearGradient>
      <linearGradient id="plata" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#b9bcc4" /><stop offset="45%" stopColor="#eceef2" /><stop offset="100%" stopColor="#9a9ea8" /></linearGradient>
    </defs>
    <rect x={-316} y={-190} width={640} height={400} rx={32} fill="rgba(0,0,0,0.4)" />
    <rect x={-320} y={-200} width={640} height={400} rx={32} fill="url(#tjG)" stroke="rgba(255,255,255,0.5)" strokeWidth={5} />
    <path d="M -320 -120 Q 0 -240 320 -60 L 320 -168 Q 320 -200 288 -200 L -288 -200 Q -320 -200 -320 -168 Z" fill="rgba(255,255,255,0.16)" />
    <g transform="translate(-200 -100)">
      <rect x={-70} y={-10} width={140} height={100} rx={10} fill="#ffd24a" stroke="#9a7a10" strokeWidth={4} />
      <rect x={-12} y={-10} width={24} height={100} fill="#e2503f" /><rect x={-70} y={30} width={140} height={22} fill="#e2503f" />
      <path d="M 0 -10 C -40 -70 -80 -20 0 -10 C 80 -20 40 -70 0 -10 Z" fill="#e2503f" stroke="#9a2a1f" strokeWidth={4} />
    </g>
    <rect x={-290} y={20} width={580} height={100} rx={14} fill="rgba(10,10,20,0.55)" />
    {!vacio && [0, 1, 2, 3, 4, 5, 6, 7].filter((i) => i >= quitados).map((i) => <Tx key={i} x={-245 + i * 70} y={90} s={56} c={col}>{'48190273'[i]}</Tx>)}
    {raspado < 1 && <rect x={-290 + 580 * raspado} y={20} width={580 * (1 - raspado) + 0.1} height={100} rx={14} fill="url(#plata)" stroke="#7a7e88" strokeWidth={3} />}
    {gris > 0 && <rect x={-320} y={-200} width={640} height={400} rx={32} fill="#8a8a8a" opacity={gris * 0.85} />}
    {children}
  </g>
);

// ================= SITIO A: la franja (E1 y E8) =================
const SitioA: React.FC = () => {
  const {s, spr} = useS();
  const p = eio(ro(s, 0.25, ESTAFA - 0.3));
  const col = tono(s, [0, ESTAFA - 0.1], [GOLD, RED], 0.3);
  const sh = sacudida(s, [ESTAFA + 0.05], 14);
  const zig = Math.sin(s * 22) * 26;
  const sello = spr(ESTAFA, 8, 150);
  const cam = ASC([W(0, 540, 1000, 1.0), W(ESTAFA - 0.2, 540, 1060, 1.6), W(ESTAFA + 3, 540, 1020, 1.3)]);
  return (
    <AbsoluteFill>
      <Camara paradas={cam}>
        <Panel i={0} base="radial-gradient(circle at 50% 42%, #5a3d14 0%, #231707 70%, #0d0903 100%)" linea="rgba(255,210,120,0.22)" luz="rgba(255,200,61,0.16)" semilla={2} br={[540, 1060, 520, 'rgba(255,200,61,0.34)']} />
        <Mundo>
          <g transform={`translate(${sh.x} ${sh.y})`}>
            <Tarjeta x={540} y={1000} k={1.5} r={-5} raspado={p} col={col}>
              {p < 1 && (
                <g transform={`translate(${-290 + 580 * p} ${70 + zig}) rotate(24)`}>
                  <rect x={-36} y={-12} width={72} height={330} rx={36} fill="#e0a878" stroke="#7a4f2c" strokeWidth={4} />
                  <ellipse cx={0} cy={22} rx={26} ry={38} fill="#f7dcc6" stroke="#b98a62" strokeWidth={3} />
                  {Array.from({length: 4}).map((_, i) => <circle key={i} cx={-30 - i * 16 - 10 * ((s * 8 + i) % 1)} cy={30 + i * 14} r={4} fill="#dfe2e8" />)}
                </g>
              )}
              {sello > 0.01 && (
                <g transform={`translate(0 -20) rotate(-12) scale(${1 + (1 - sello) * 2.4})`} opacity={cl(sello)}>
                  <rect x={-230} y={-60} width={460} height={120} rx={14} fill="rgba(255,255,255,0.1)" stroke={RED} strokeWidth={12} />
                  <Tx x={0} y={32} s={96} c={RED}>ESTAFA</Tx>
                </g>
              )}
            </Tarjeta>
          </g>
        </Mundo>
        <Ondas x={540} y={1000} t0={ESTAFA} color={RED} radio={440} />
      </Camara>
    </AbsoluteFill>
  );
};

// ================= SITIO B: la sala y el telefono (E2) =================
const Icono: React.FC<{x: number; y: number; t0: number; tipo: number}> = ({x, y, t0, tipo}) => {
  const {s, spr} = useS();
  const k = spr(t0, 10, 190);
  if (k < 0.01) return null;
  const fl = Math.sin(s * 2 + tipo * 2) * 10;
  return (
    <g transform={`translate(${x} ${y + fl}) scale(${k})`}>
      <circle r={96} fill="rgba(20,16,10,0.72)" stroke={GOLD} strokeWidth={6} />
      {tipo === 0 && <g><path d="M -60 -20 L 0 -66 L 60 -20 Z" fill="#e8d9a8" stroke="#7a6a30" strokeWidth={4} />{[-42, -14, 14, 42].map((cx, i) => <rect key={i} x={cx - 8} y={-14} width={16} height={56} fill="#e8d9a8" stroke="#7a6a30" strokeWidth={3} />)}<rect x={-66} y={46} width={132} height={14} fill="#e8d9a8" stroke="#7a6a30" strokeWidth={3} /></g>}
      {tipo === 1 && <g><rect x={-46} y={-62} width={92} height={124} rx={8} fill="#f3f3ee" stroke="#8d8d84" strokeWidth={4} />{[-32, -10, 12].map((yy, i) => <line key={i} x1={-30} y1={yy} x2={30} y2={yy} stroke="#8d8d84" strokeWidth={5} />)}<Tx x={0} y={52} s={34} c={RED}>%</Tx></g>}
      {tipo === 2 && <g><circle cy={-12} r={44} fill="#ffe14a" stroke="#a88a10" strokeWidth={5} /><rect x={-20} y={28} width={40} height={30} rx={6} fill="#9a9a90" stroke="#4a4a44" strokeWidth={4} /><path d="M -44 -12 L -66 -12 M 44 -12 L 66 -12 M 0 -56 L 0 -78" stroke="#ffe14a" strokeWidth={6} strokeLinecap="round" /></g>}
    </g>
  );
};
const SitioB: React.FC = () => {
  const {s, spr} = useS();
  const suena = s < DICEN ? 1 : 0;
  const shake = Math.sin(s * 46) * 4 * suena;
  const mano = eo(ro(s, LLAMAN + 0.05, DICEN + 0.2));
  const reloj = spr(HOY, 10, 170);
  const cam = ASC([W(0, 540, 1000, 1.0), W(HOY + 1.2, 540, 1150, 1.3)]);
  return (
    <AbsoluteFill>
      <Camara paradas={cam}>
        <Panel i={0} base="linear-gradient(180deg, #5a3a1c 0%, #3a2410 55%, #26160a 56%, #150c05 100%)" linea="rgba(255,200,120,0.18)" luz="rgba(255,200,61,0.14)" semilla={4} br={[820, 560, 420, 'rgba(255,200,61,0.40)']} />
        <Mundo>
          <rect x={0} y={1340} width={1080} height={580} fill="#2a1a0c" /><rect x={0} y={1330} width={1080} height={22} fill="#7a5530" />
          <ellipse cx={540} cy={1500} rx={300} ry={26} fill="rgba(0,0,0,0.45)" />
          <path d="M 800 560 L 800 760 M 740 560 L 860 560 L 830 460 L 770 460 Z" fill="#ffd27a" stroke="#7a5530" strokeWidth={6} />
          {suena > 0 && [0, 1, 2].map((i) => { const q = (s * 1.4 + i / 3) % 1; return <circle key={i} cx={540} cy={1150} r={170 + q * 250} fill="none" stroke={GOLD} strokeWidth={6} opacity={0.6 * (1 - q)} />; })}
          <Cel x={540 + shake} y={1150 - 90 * mano} k={0.4} r={shake * 0.8} pantalla="#101a28">
            <circle cy={-60} r={110} fill={suena ? GOLD : '#3a8a55'} opacity={0.9} />
            <Tx x={0} y={-30} s={100} c="#101a28">{suena ? '...' : 'OK'}</Tx>
            <Tx x={0} y={240} s={60} c="#fff">Banco?</Tx>
          </Cel>
          <Mano x={1000 - 460 * mano} y={1560 - 360 * mano} r={-24} k={0.62} piel="media" dedo={false} />
          <Icono x={230} y={600} t0={BANCO} tipo={0} />
          <Icono x={850} y={700} t0={IMPUESTOS} tipo={1} />
          <Icono x={540} y={480} t0={LUZ} tipo={2} />
          {reloj > 0.01 && (
            <g transform={`translate(840 1560) scale(${reloj + 0.1 * golpe(s, HOY, 20, 6)})`}>
              <circle r={120} fill="#fff" stroke={RED} strokeWidth={14} />
              {Array.from({length: 12}).map((_, i) => <line key={i} x1={0} y1={-100} x2={0} y2={-88} stroke="#333" strokeWidth={5} transform={`rotate(${i * 30})`} />)}
              <line x1={0} y1={0} x2={0} y2={-80} stroke={RED} strokeWidth={9} strokeLinecap="round" transform={`rotate(${(s - HOY) * 300})`} />
              <line x1={0} y1={0} x2={0} y2={-52} stroke="#222" strokeWidth={11} strokeLinecap="round" transform={`rotate(${(s - HOY) * 25})`} />
              <circle r={10} fill="#222" />
              <Tx x={0} y={190} s={64} c={RED}>HOY</Tx>
            </g>
          )}
        </Mundo>
      </Camara>
    </AbsoluteFill>
  );
};

